    public static void onRenderLevel(RenderLevelStageEvent event) {
        if (event.getStage() == RenderLevelStageEvent.Stage.AFTER_SKY) {
            // Custom rendering after sky
            Minecraft mc = Minecraft.getInstance();
            if (mc.player != null) {
                // Draw custom effects
            }
        }
    }

